    labelAudio: 'آڊيو پوسٽون:',
    uploadAudio: 'ميوزڪ ۽ ڳالهائيندڙ آڊيو پوسٽ ڪنهن ٻئي شڪل وانگر، ڪارڊ تي هڪ ويزولائزر سان ۽ هڪ ڪنڊ پليئر جيڪو راند ڪندو رهي ٿو جڏهن ته توهان فيڊ کي اسڪرول ڪرڻ تي کڻندا آهيو.',
    tocAllowance: 'پوسٽنگ الائونس',
    allowanceTitle: 'روزاني پوسٽنگ الائونس',
    allowanceIntro: 'DeHub تي پوسٽ ڪرڻ هر روز مفت آهي، هڪ الائونس تائين جيڪو توهان جي اسٽيڪنگ بيج سان اسڪيل ڪري ٿو. هرڪو شروع ٿئي ٿو ڏهن ٽيڪسٽ پوسٽن ۽ هر ڏينهن جي وڊيو، تصويرون ۽ آڊيو جي هڪ گيگا بائيٽ سان. يا ته هڪ گذري وڃو ۽ باقي ڏينهن DeHub ٽوڪن ۾ ادا ڪيو ويندو آهي — 10C هڪ متن پوسٽ، $ 2 هڪ گيگابائيٽ، صرف انهي حصي تي چارج ڪيو ويو آهي جيڪو مٿان هلندو آهي.',
    allowanceIntro2: 'ٽيڪسٽ پوسٽون ۽ ميڊيا الڳ پول آهن. هڪ کان ٻاهر هلڻ ٻئي کي ڇڪي نه ٿو، تنهن ڪري هڪ ڏينهن ويڊيو اپ لوڊ ڪرڻ ۾ گذاريو اڃا تائين سڀني ڏهن متن پوسٽن کي مفت ڇڏي ٿو. ٻئي اڌ رات جو UTC تي ري سيٽ.',
    allowanceHowTitle: 'ڪيئن ادائگي ڪم',
    allowanceHowDesc: 'آرڊر اهم آهي، ۽ اهو ڄاڻي واڻي آهي: توهان کي ڪڏهن به هڪ پوسٽ لاء چارج نه ڪيو ويو آهي جيڪو شايع نه ڪيو ويو آهي، ۽ توهان ڪڏهن به هڪ وڏي فائل اپ لوڊ نه ڪيو آهي صرف بعد ۾ ٻڌايو وڃي ته توهان ان لاء ادا نه ڪري سگهو ٿا.',
    allowanceStep1Title: 'اپ لوڊ ڪرڻ کان اڳ',
    allowanceStep1: 'ايپ قيمت جي چڪاس ڪري ٿي ان جي خلاف جيڪو توهان ا already ۾ ئي پوسٽ ڪيو آهي ۽ تصديق ڪري ٿو ته توهان جو پرس ان کي coverڪي سگهي ٿو. ڪجھ به چارج نه ڪيو ويو آهي، ۽ ڪجھ به اپ لوڊ نه ڪيو ويو آهي جيستائين اهو گذري وڃي.',
    allowanceStep2Title: 'تحرير رائع',
    allowanceStep2: 'توهان جي پوسٽ صحيح طور تي زنده رهي ٿي جئين اهو مفت الائونس جي اندر هوندو. اشاعت ڪڏهن به ادائيگي تي انتظار نه ڪندي آهي.',
    allowanceStep3Title: 'ان کان پوء اوھان کي ادا',
    allowanceStep3: 'هڪ منتقلي، هڪ دستخط، صرف انهي پوسٽ لاءِ. اهو ڪنهن به بنياد يا BNB زنجير جو ڪافي DeHub ٽوڪن قيدين تي آباد.',
    allowanceUnpaidTitle: 'جيڪڏهن توهان رد ڪريو ٿا',
    allowanceUnpaidDesc: 'تحرير رائع رهيب. غير ادا ڪيل رقم توهان جي اڪائونٽ جي خلاف کليل رهي ٿي ۽ توهان جي ايندڙ ادا ڪيل پوسٽ کي روڪي ٿي جيستائين اهو آباد نه ٿئي — پر ڪڏهن به مفت ناهي. سڀاڻي جو الائونس جيڪو به توهان کي ڏئي ٿو اهو هميشه توهان جو آهي، ڇا ڪجهه به بقايا آهي يا نه.',
    allowanceCountsTitle: 'ان جي خلاف ڇا ڳڻتي آهي',
    allowanceCounts1: 'صرف ٽيڪسٽ پوسٽون هر هڪ توهان جي روزاني ٽيڪسٽ پوسٽن مان هڪ خرچ ڪن ٿيون.',
    allowanceCounts2: 'وڊيو، تصويري ۽ آڊيو پوسٽون انهن جي فائل جي سائيز کي ڊيٽا الائونس جي خلاف خرچ ڪن ٿيون — ٿمبنيل شامل آهن، جڏهن کان اهي ذخيرو ڪيا ويا آهن ۽ پڻ خدمت ڪيا ويا آهن.',
    allowanceCounts3: 'اقتباس پوسٽون صحيح طور تي انهي پوسٽ وانگر ڳڻپ ڪن ٿيون جيڪي اهي آهن: هڪ وڊيو منسلڪ سان گڏ هڪ اقتباس ڊيٽا خرچ ڪري ٿو.',
    allowanceCounts4: 'اوورائيج پرو- رتا آهي، پوري گيگابائيٽ تائين گول نه آهي. جيڪڏهن اپلوڊ جو 200 ايم بي توهان جي الائونس کان اڳتي هلندو آهي، توهان 200 ايم بي جي ادائيگي ڪريو ٿا.',
    allowanceCounts5: 'Reposts، تبصرا، رد عمل، ٽوٽڪا ۽ پيغام ڪجھ به خرچ نه ڪندا آهن ۽ ڪڏهن به الائونس کي نه ڇڪيندا آهن.',
    allowanceBadgeNote: 'هڪ بيج ٻنهي کي هڪ ئي وقت هلائي ٿو — هڪ وڏو مفت الائونس ۽ ان کان اڳ جي ڪنهن به شيءِ تي گهٽ قيمت. رعايت ساڳئي ڏاڪڻ بيج هولڊر اڳ ۾ ئي حاصل ڪندا آهن جڏهن DeHub ٽوڪن خريد ڪندا آهن، ڪرب تي 5 سيڪڙو کان 30 سيڪڙو تائين ميگالوڊون تي، تنهن ڪري هڪ جواب آهي ته بيج جي قيمت ڇا آهي. توھان جو الائونس انھيءَ بيج مان ايندو آھي جنھن کي توھان ڪمايو آھي: ھڪڙو درجو جيڪو توھان کي توھان جي پروفائل تي سرپرست شوز ذريعي قرض ڏنو ويو آھي، پر اھو توھان کي انھن جي پوسٽنگ الائونس نٿو ڏئي.',
