    tokenisedDesc: 'DeHub تي ڪنهن به اپلوڊ يا لائيو اسٽريم کي ERC -1155 NFT جي طور تي منٿ ڪري سگهجي ٿو جيڪو صحيح طور تي 1،000 ٽڪرن ۾ ڀريل آهي. منٽنگ اختياري آهي: هڪ پوسٽ شايع ڪري ٿي آف زنجير ان لمحو جڏهن توهان ان کي موڪليو ٿا — نه پرس، نه دستخط، نه گئس — ۽ توهان اهو ڪري سگهو ٿا جڏهن به توهان چاهيو ٿا پوسٽ پاڻ کان. هڪ دفعو منٿ ڪئي وئي، تخليق ڪندڙن کي مڪمل ڪنٽرول آهي ته ڪيترا حصا وڪڻڻ يا رکڻ لاءِ، هڪ ناول monetization ماڊل ٺاهڻ جتي مداح مواد ۾ سيڙپڪاري ڪري سگهن ٿا اهي يقين رکن ٿا ته ڪامياب ٿي ويندا - بنيادي طور تي فين ٽوڪن جي انقلابي شڪل ذريعي امڪاني ستارن جي مستقبل تي "بيٽنگ".',
