    mineSubtitle: 'Decentralized اعتدال کني ۽ آمدني شيئر ماڊل',
    mineDesc2: 'صرف بنيادي ٽيم يا مٿين ٽائر بيج هولڊرز کي اين ايف ٽي سان لاڳاپيل ساڙڻ سان فوري طور تي هڪ وڊيو ختم ڪرڻ جي طاقت هوندي. ان کان پوء، سڀني اشتهارن جي آمدني پيدا ڪئي وئي ۽ وڊيو تي تنگ ٿيل بونس ڪمائڻ لاءِ ڪنهن به راند کي خراب اداڪارن کي وڌيڪ روڪڻ ۽ هڪ مصروف برادري جي حوصلا افزائي ڪرڻ لاءِ سڀني ووٽنگ والٽ سان شيئر ڪيو ويندو.',
    mineDynamic: 'سڀني افاديت لاء گهربل DeHub ٽوڪن جي رقم هڪ متحرڪ متغير آهي، تنهنڪري قيمت جي حوالي سان ڪنهن به وقت تبديل ٿيڻ گهرجي. ڪنهن به تبديلي جو اعلان سڀني سرڪاري چينلن تي عوامي طور تي ڪيو ويندو.',
