    feedsDesc: 'DeHub گهر جي مٿاڇري هڪ واحد ٽيب فيڊ آهي جيڪو هر مواد جي شڪل کي هڪ ئي وقت کڻندو آهي. تخليق ڪندڙن کي هڪ وچولي ۾ مجبور ڪرڻ جي بدران، فيڊ متن، تصويرون، ڊگهي شڪل واري وڊيو، مختصر شڪل واري ريل، ميوزڪ ۽ لائيو اسٽريمز کي هڪ اسڪرول ۾ ملائي ٿو، ۽ ناظرین کي هڪ ئي شڪل ۾ تنگ ڪري ٿو جڏهن اهي چاهيندا آهن. هر ڪارڊ، فارميٽ جي قطع نظر، ساڳيو سماجي ۽ monetization ڪنٽرول کڻندو آهي: جهڙوڪ، تبصرو، ٻيهر پوسٽ، اقتباس، بک مارڪ ۽ ڊي هب ٽوڪن ۾ ٽپ.',
    feedsDesc2: 'کاڌ خوراڪ جي مٿاڇري تي ٽئب جي طور تي فارميٽ سامهون اچن ٿا. ڊفالٽ هوم ٽيب توهان جي پيروي ڪندڙ ماڻهن ۽ برادرين مان هر شي کي مداخلت ڪري ٿو ؛ وقف ٿيل ٽيب هڪ وچولي کي ڌار ڪري ٿو ته توهان ڪري سگهو ٿا، مثال طور، صرف ڊگهي شڪل واري وڊيو يا صرف ميوزڪ براؤز ڪريو. درجه بندي هن صفحي تي وڌيڪ دستاويز ڪيل پليٽ فارم ليڊر بورڊ الگورتھم طرفان هلائي وئي آهي، تنهن ڪري معيار ۽ مصروفيت، اشتهار خرچ نه، پهچڻ جو فيصلو ڪريو.',
