    feedsBookmarksDesc: 'بعد ۾ توهان جي نجي بک مارڪس تي ڪنهن به پوسٽ کي محفوظ ڪريو، ۽ پليٽ فارم ليڊر بورڊ تي مٿين تخليق ڪندڙن کي ٽريڪ ڪريو، هيٺ ڏنل بيان ڪيل الگورتھم طرفان درجه بندي ڪئي وئي آهي.',
