    studioDesc2: 'ان جي اڳيان هڪ مڪمل وڊيو ايڊيٽر آهي جيڪو برائوزر ۾ هلندو آهي — ڪٽڻ، پرت ۽ برآمد سان گڏ هڪ حقيقي ملٽي ٽريڪ ٽائم لائن، نه ٽرم سلائيڊر. فوٽو جيڪو توهان اسٽوڊيو ۾ ٺاهيو، ميڊيا جيڪو توهان اپ لوڊ ڪيو ۽ اثاثن جي لائبريري مان ڪجهه به ساڳئي ٽائم لائن تي اچي ٿو، ۽ ختم ٿيل ڪٽ سڌي طرح هڪ پوسٽ، هڪ مختصر يا اسٽور لسٽنگ ۾ وڃي ٿو.',
