    q11: 'DeHub محفوظ آهي ؟',
    a11: 'ها، DeHub Certik طرفان سيڪيورٽي آڊٽ ڪئي آهي ۽ بگ بائونٽي پروگرام کي برقرار رکندو آهي. اسان پنهنجي سڀني سمارٽ معاهدن ۽ انفراسٽرڪچر ۾ حفاظت کي ترجيح ڏيون ٿا.',
