    q16: 'Phygital NFT مارڪيٽ ڇا آهي ؟',
    a16: 'اسان جي مارڪيٽ جي جڳھ صارفين کي ڊي هب ٽوڪن استعمال ڪندي ڊجيٽل مجموعي، جسماني اثاثن، ۽ خدمتن کي خريد ڪرڻ جي اجازت ڏئي ٿو، جسماني ۽ ڊجيٽل ملڪيت جي وچ ۾ فرق کي ختم ڪري ٿو.',
    q17: 'آئون DeHub جي ڊي ايپس تائين ڪيئن رسائي حاصل ڪري سگهان ٿو ؟',
    a17: 'توهان اسان جي مکيه پليٽ فارم ذريعي DeHub جي ڊي ايپس تائين رسائي ڪري سگهو ٿا. DeHub ٽوڪن هولڊرز سڀني موجوده ۽ مستقبل جي ڊي ايپس ۾ وڌايل خاصيتون ۽ ڪارڪردگي حاصل ڪن ٿا.',
    q18: 'DeHub جو روڊ ميپ ڇا آهي ؟',
    a18: 'اسان جي روڊ ميپ ۾ ڊي ايپ ايڪو سسٽم کي وڌائڻ، نئين رانديون لانچ ڪرڻ، ڊيپين انفراسٽرڪچر کي وڌائڻ، اي آءِ ٽول ڪٽس کي ترقي ڪرڻ، ۽ پليٽ فارم وائيڊ گورننس رول آئوٽ جاري رکڻ شامل آهن.',
    q19: 'آئون DeHub ٽيم سان ڪيئن رابطو ڪري سگهان ٿو ؟',
    a19: 'توهان اسان جي سرڪاري چينلز ذريعي اسان تائين پهچي سگهو ٿا: tech @ dehub. net ٽيڪنيڪل مسئلن لاءِ، يا تازه ڪاري ۽ ڪميونٽي جي مصروفيت لاءِ Twitter ۽ Instagram @ dehub_official تي اسان جي پيروي ڪريو.',
    q20: 'ڇا DeHub ٽوڪن هڪ سيڙپڪاري آهي ؟',
    a20: 'نه، DeHub ٽوڪن سختي سان DeHub ايڪو سسٽم جي اندر افاديت جي مقصدن لاء آهن، جهڙوڪ راند ۾ يا ايپ ۾ ڊجيٽل ڪرنسي. اهي سيڙپڪاري جا اوزار نه آهن ۽ بازارون انتهائي وولٽيل آهن.',
    q21: 'DeHub تي مواد جي اعتدال ڪيئن ڪم ڪندو آهي ؟',
    q22: 'مون کي سائن اپ ڪيئن ڪندا? مون کي هڪ crypto پرس جي ضرورت ڪندا?',
    a22: 'نه. توهان گوگل يا ايپل سان سائن ان ڪري سگهو ٿا، توهان جي اي ميل پتي ڏانهن موڪليل ڪوڊ سان، يا ايس ايم ايس طرفان موڪليل ڪوڊ سان، ۽ پس منظر ۾ توهان جي لاءِ غير محفوظ ٿيل والٽ ٺاهيو ويو آهي — توهان ڪيز رکندا آهيو ۽ اسان ڪڏهن به حراست ۾ نه وٺندا آهيون. جيڪڏھن توھان وٽ ا already ۾ ئي پرس آھي توھان ان جي بدران ان کي ڳن canي سگھوٿا. سائن ان ڪريو جيڪي والٽ تي ٻڌل نه آهن انهن جي گئس فيس پڻ اسپانسر ٿيل آهي، تنهن ڪري توهان ڪڏهن به ڏيهي ٽوڪن خريد ڪرڻ کانسواءِ پوسٽ، ٽپ ۽ گڏ ڪري سگهو ٿا.',
    q23: 'ڇا پوسٽنگ مفت آهي ؟',
    a23: 'ها، هڪ روزاني الائونس تائين جيڪو توهان جي اسٽيڪنگ بيج سان ماپ ڪري ٿو. هر اڪائونٽ ۾ ڏهه ٽيڪسٽ پوسٽون ۽ هڪ گيگا بائيٽ وڊيو، تصويرون ۽ آڊيو مفت هر ڏينهن، ۽ ٻئي تلاءَ آڌي رات يو ٽي سي تي ري سيٽ ڪندا آهن. ته ماضي ۾, ته ڏينهن جي باقي DeHub ٽوڪن ۾ قيمتي آهي — لڳ ڀڳ 10C هڪ متن تحرير ۽ $ 2 هڪ gigabyte, الزام نواز- rata ۽ صرف حصو آهي ته مٿان ڊوڙندو تي. تحريرون، تبصرا، رد عمل، صلاحون ۽ پيغام ڪڏهن به ان جي خلاف شمار نه ڪندا آهن.',
    q24: 'مون کي NFTs جي طور تي منهنجي تحريرن mint ڪرڻ جي ضرورت آهي ڇا ؟',
    a24: 'نه. Minting اختياري آهي. هڪ پوسٽ اشاعت بند- زنجير جڏهن توهان ان کي موڪلي ٿو, ڪو پرس جي دستخط ۽ ڪو گئس سان, ۽ اوھان کي بعد ۾ ان جي پوسٽ پاڻ کان mint ڪري سگهو ٿا ته توهان جي ERC -1155 ۽ شاهي ته ان سان گڏ اچي ٿو چاهيون ٿا.',
    q25: 'هڪ اسٽيڪنگ بيج اصل ۾ مون کي ڇا حاصل ڪري ٿو ؟',
    a25: 'هڪ بيج توهان جي پليٽ فارم فيس کي 0.69 ٪ في ٽائر گهٽائي ٿو، توهان جي مفت روزاني پوسٽنگ الائونس کي وڌائي ٿو ۽ ان کان اڳ جي ڪا به رعايت، توهان کي ساڳيو 5 ٪-30 ٪ رعايت ڏئي ٿو جڏهن DeHub ٽوڪن خريد ڪيو، سپر پاورز ۽ پروفائل کاسمیٹڪس کي کوليو، ۽ توهان جي خيالن ۽ رد عمل کي وڌيڪ لاءِ ڳڻپيو. تيرهن ٽائر ٽڪن جي مقرر ڪيل تعداد جي بدران ڊالر ۾ قيمتي آهن، ۽ هڪ ڀيرو توهان هڪ ٽائر ڪمايو آهي ته قيمت توهان کي واپس نه وٺي سگهي.',
    q26: 'ڇا آئون پنهنجو بيج ڪنهن ٻئي کي قرض ڏئي سگهان ٿو ؟',
