    disclaimerText: 'DeHub ٽوڪن سختي سان افاديت جي مقصدن لاءِ ساڳئي طريقي سان آهن جيڪي ڪنهن به راند ۾ يا ايپ ۾ ڊجيٽل ٽوڪن يا ڪرنسي ۽ سختي سان سيڙپڪاري نه آهن. جئين اسان جو ٽوڪن آن چين جي زندگي گذاريندو آهي، اسان اضافي افاديت سان گڏوگڏ قابل تصديق شفافيت جي بي مثال سطح پيش ڪري سگهون ٿا. مٿين ڊيٽا صرف شفافيت، تعليمي ۽ معلوماتي مقصدن لاءِ مرتب ڪئي وئي آهي. DeHub ۽ سڀني ساٿي ادارن جي مالي نقصانن جي ڪا ذميواري ناهي جيڪا اسان جاري ڪيل ڪنهن به ٽوڪن يا اين ايف ٽي خريد ڪرڻ کان ٿيندي آهي. بازارون انتهائي وولٽيل آهن. توهان ڪنهن به اڻڄاتل غلطين جهڙوڪ قابليت جي ناڪامي، فني غلطي، هيڪس ۽ انهي جي ڪري پڻ پنهنجو سڀ پئسا وڃائي سگهو ٿا. بس جيڪي ڪندا آھيو تنھن لاء شڪر ڪرڻ جي سکڻ.',
